    private static final Vec2f[] CLOCK_POS = new Vec2f[]{new Vec2f(0.5f, 0.5f), new Vec2f(0.5f, 0.0f), new Vec2f(0.0f, 0.0f), new Vec2f(0.0f, 1.0f), new Vec2f(1.0f, 1.0f), new Vec2f(1.0f, 0.0f)};
    private int max_stack;
    private int stack_expire_time;
    private final AnimationManager.AnimationAccessor<? extends StaticAnimation> sheathInAnimation = AnimationsX.BIPED_UCHIGATANA_SCRAP;
    private final AnimationManager.AnimationAccessor<? extends AttackAnimation> sheathInSkillAnimation = ExtraAnimations.UCHIGATANA_SHEATH_SKILL_01;
    private final AnimationManager.AnimationAccessor<? extends StaticAnimation> swordOutAnimation = ExtraAnimations.UCHIGATANA_UNSHEATHE;
    private final AnimationManager.AnimationAccessor<? extends AttackAnimation> swordOutSkillAnimation = ExtraAnimations.UCHIGATANA_SKILL_01;
    private static final List<DelayedAttack> DELAYED_ATTACKS = new CopyOnWriteArrayList<DelayedAttack>();

    private static void onServerTick(TickEvent.ServerTickEvent event) {
        if (event.phase == TickEvent.Phase.END && !DELAYED_ATTACKS.isEmpty()) {
            DELAYED_ATTACKS.removeIf(DelayedAttack::tick);
        }
    }

    public KatanaInnate(SkillBuilder<? extends EFXWeaponInnateBase> builder) {
        super(builder);
    }

    public void setParams(CompoundTag parameters) {
        super.setParams(parameters);
        this.max_stack = parameters.m_128451_("max_stack");
        if (this.max_stack <= 0) {
            this.max_stack = 5;
        }
        this.stack_expire_time = parameters.m_128451_("stack_expire_time");
        if (this.stack_expire_time <= 0) {
            this.stack_expire_time = 12;
        }
    }

    private int getDynamicMaxStack(SkillContainer container) {
        int sweepingLevel = ((Player)container.getExecutor().getOriginal()).m_21205_().getEnchantmentLevel(Enchantments.f_44983_);
        return this.max_stack + sweepingLevel;
    }

    public boolean resourcePredicate(PlayerPatch<?> playerpatch, SkillCastEvent event) {
        return true;
    }

