@Override
public void onInitiate(SkillContainer container) {
    super.onInitiate(container);
    this.setSheathRenderState(container, true);
    container.getExecutor().getEventListener().addEventListener(PlayerEventListener.EventType.ACTION_EVENT_SERVER, ACTION_EVENT_SERVER_UUID, event -> {
        AnimationManager.AnimationAccessor realAnim = ((MainFrameAnimation)event.getAnimation().get()).getRealAnimation();
        if (realAnim.equals(((AttackAnimation)this.sheathInSkillAnimation.get()).getRealAnimation()) || realAnim.equals(((AttackAnimation)this.swordOutSkillAnimation.get()).getRealAnimation())) {
            return;
        }
        if (event.getAnimation().get() instanceof AttackAnimation) {
            int dynamicMaxStack = this.getDynamicMaxStack(container);
            int currentCount = (Integer)container.getDataManager().getDataValue((SkillDataKey)EFXSkillDataKeys.ATTACK_COUNT.get());
            if (currentCount < dynamicMaxStack) {
                container.getDataManager().setDataSync((SkillDataKey)EFXSkillDataKeys.ATTACK_COUNT.get(), (Object)(currentCount + 1));
            }
        }
    });
    container.getExecutor().getEventListener().addEventListener(PlayerEventListener.EventType.TAKE_DAMAGE_EVENT_ATTACK, TAKE_DAMAGE_EVENT_ATTACK_UUID, event -> {
        if (this.isTransformSkillAnimation(container.getExecutor()) && container.getExecutor().getEntityState().inaction()) {
            DamageSource damageSource = event.getDamageSource();
            event.setResult(AttackResult.ResultType.MISSED);
            event.setCanceled(true);
            if (!((AttackResult.ResultType)DodgeAnimation.DODGEABLE_SOURCE_VALIDATOR.apply(damageSource)).dealtDamage()) {
                container.getExecutor().onDodgeSuccess(damageSource, ((Player)container.getExecutor().getOriginal()).m_20191_().m_82363_(1.0, 0.0, 1.0).m_82399_());
            }
        }
    });

