public class BattojutsuPassiveX
extends Skill {
    private static final UUID EVENT_UUID = UUID.fromString("a416c93a-42cb-21eb-b378-0252ac130003");
    private static final UUID PLAYER_KILLED_EVENT = UUID.fromString("a416c93a-42cb-21eb-b378-0252ac130004");

    public BattojutsuPassiveX(SkillBuilder<? extends Skill> builder) {
        super(builder);
    }

    public void onInitiate(SkillContainer container) {
        super.onInitiate(container);
        if (this.isHoldingWeapon(container)) {
            this.setSheathRenderState(container, false);
        }
        container.getExecutor().getEventListener().addEventListener(PlayerEventListener.EventType.ACTION_EVENT_SERVER, EVENT_UUID, event -> {
            if (!(event.getAnimation().get() instanceof DodgeAnimation)) {
                container.getSkill().setConsumptionSynchronize(container, 0.0f);
                container.getSkill().setStackSynchronize(container, 0);
            }
        });
